def solve_task(grid):
    """
    Rule: Fill between non-background cells (horizontally and vertically).
    Fill a cell with 2 if it's between two non-background cells in the same row OR same column.
    """
    bg = grid[0][0]  # Background color

    # Find all non-background cells
    non_bg = []
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val != bg:
                non_bg.append((i, j))

    # Create output (copy of input)
    out = [row[:] for row in grid]

    # Fill horizontally: for each row, find consecutive non-bg cells and fill between
    for i in range(len(grid)):
        cols = sorted([j for j in range(len(grid[i])) if grid[i][j] != bg])
        for k in range(len(cols) - 1):
            for c in range(cols[k] + 1, cols[k+1]):
                if 0 <= c < len(grid[i]):
                    out[i][c] = 2

    # Fill vertically: for each col, find consecutive non-bg cells and fill between
    for j in range(len(grid[0])):
        rows = sorted([i for i in range(len(grid)) if grid[i][j] != bg])
        for k in range(len(rows) - 1):
            for r in range(rows[k] + 1, rows[k+1]):
                if 0 <= r < len(grid):
                    out[r][j] = 2

    return out

